static const int wwdr_count = (int)(sizeof wwdr / sizeof wwdr[0]);

// ---------- разбор Name из сертификата и подбор промежуточного ----------
static int w_tlv(const unsigned char **p, const unsigned char *e, unsigned *tag,
                 const unsigned char **v, size_t *vl) {
    if (*p >= e) return 0;
    unsigned t = *(*p)++;
    if ((t & 0x1f) == 0x1f || *p >= e) return 0;
    size_t len; unsigned b = *(*p)++;
    if (b < 0x80) len = b;
    else { int nb = b & 0x7f; if (nb == 0 || nb > 4 || *p + nb > e) return 0; len = 0; while (nb--) len = (len << 8) | *(*p)++; }
    if ((size_t)(e - *p) < len) return 0;
    *tag = t; *v = *p; *vl = len; *p += len; return 1;
}

int gx_cert_name(const unsigned char *cert, size_t n, int which, const unsigned char **outp, size_t *outlen) {
    const unsigned char *p = cert, *e = cert + n, *v; unsigned tag; size_t vl;
    if (!w_tlv(&p, e, &tag, &v, &vl) || tag != 0x30) return 0;            // Certificate
    const unsigned char *tp = v, *te = v + vl;
    if (!w_tlv(&tp, te, &tag, &v, &vl) || tag != 0x30) return 0;          // tbsCertificate
    const unsigned char *q = v, *qe = v + vl;
    if (!w_tlv(&q, qe, &tag, &v, &vl)) return 0;                         // [0] version ИЛИ serialNumber
    if (tag == 0xA0 && !w_tlv(&q, qe, &tag, &v, &vl)) return 0;          // была version → читаем serialNumber
    if (!w_tlv(&q, qe, &tag, &v, &vl)) return 0;                         // signature AlgId
    const unsigned char *istart = q;                                    // issuer Name
    if (!w_tlv(&q, qe, &tag, &v, &vl) || tag != 0x30) return 0;
    if (which == 0) { *outp = istart; *outlen = (size_t)(q - istart); return 1; }
    if (!w_tlv(&q, qe, &tag, &v, &vl)) return 0;                         // validity
    const unsigned char *sstart = q;                                    // subject Name
    if (!w_tlv(&q, qe, &tag, &v, &vl) || tag != 0x30) return 0;
    *outp = sstart; *outlen = (size_t)(q - sstart); return 1;
}

const unsigned char *gx_wwdr_for_issuer(const unsigned char *issuer_der, size_t issuer_len, size_t *out_len) {
    for (int i = 0; i < wwdr_count; i++) {
        const unsigned char *sp; size_t sl;
        if (gx_cert_name(wwdr[i].der, wwdr[i].len, 1, &sp, &sl) && sl == issuer_len && !memcmp(sp, issuer_der, issuer_len)) {
            *out_len = wwdr[i].len; return wwdr[i].der;
        }
    }
    return NULL;
}
